// Generated mobile deployment package. Editable sources are in the source archive.
const fs=require('node:fs'),path=require('node:path'),zlib=require('node:zlib');
const files={"icon.svg": "", "index.html": "", "assets/lakeside.webp": "", "assets/tower.webp": "", "assets/village.webp": ""};
for(const [name,content] of Object.entries(files)){
 const dest=path.join('dist',name);
 fs.mkdirSync(path.dirname(dest),{recursive:true});
 fs.writeFileSync(dest,zlib.gunzipSync(Buffer.from(content,'base64')));
}
